def subarray_sum(nums: list[int], s: int) -> list[int]:
    if s <= 0:
        return [-1]
    left = 0
    curr_sum = 0
    for right in range(len(nums)):
        curr_sum += nums[right]
        while curr_sum > s and left < right:
            curr_sum -= nums[left]
            left += 1
        if curr_sum == s:
            return [left + 1, right + 1]
    return [-1]
